db:insert.db:input-parameters:
#[{
  clientId: vars.clientId,
  clientSecret: vars.clientSecret,
  userId: vars.userId,
  salesforceUserId: vars.salesforceUserId
}]

ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  status: "success",
  message: "API connection disconnected successfully",
  userId: vars.salesforceUserId,
  clientId: vars.clientId,
  timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"}
}

%dw 2.0
output application/json
---
{
  status: "not_found",
  message: "No active API connection found for this user",
  userId: vars.salesforceUserId,
  clientId: vars.clientId,
  timestamp: now() as String {format: "yyyy-MM-dd'T'HH:mm:ss'Z'"}
}

%dw 2.0
output application/json
---
{
  "message": "No goals found for employee " ++ (vars.employeeId default "unknown")
}
